// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListEstimates Версии оценки потребности, новые первыми
	// (GET /estimates)
	ListEstimates(ctx context.Context, request ListEstimatesRequestObject) (ListEstimatesResponseObject, error)
	// CalculateEstimate Рассчитать версию по явно выбранным входам (демо-формулы)
	// (POST /estimates)
	CalculateEstimate(ctx context.Context, request CalculateEstimateRequestObject) (CalculateEstimateResponseObject, error)
	// GetEstimate Оценка с версиями входов и потребностью клиник
	// (GET /estimates/{id})
	GetEstimate(ctx context.Context, request GetEstimateRequestObject) (GetEstimateResponseObject, error)
	// PublishEstimate Подтвердить публикацию версии; повтор идемпотентен
	// (POST /estimates/{id}/publish)
	PublishEstimate(ctx context.Context, request PublishEstimateRequestObject) (PublishEstimateResponseObject, error)
	// RejectEstimate Отклонить рассчитанную версию с причиной, повтор идемпотентен
	// (POST /estimates/{id}/reject)
	RejectEstimate(ctx context.Context, request RejectEstimateRequestObject) (RejectEstimateResponseObject, error)
	// ListFiles Загруженные файлы, новые первыми
	// (GET /files)
	ListFiles(ctx context.Context, request ListFilesRequestObject) (ListFilesResponseObject, error)
	// UploadFile Загрузить файл CSV и получить результат проверки
	// (POST /files)
	UploadFile(ctx context.Context, request UploadFileRequestObject) (UploadFileResponseObject, error)
	// GetFile Файл и итог его проверки
	// (GET /files/{id})
	GetFile(ctx context.Context, request GetFileRequestObject) (GetFileResponseObject, error)
	// ListFileErrors Отклонённые строки файла с причинами
	// (GET /files/{id}/errors)
	ListFileErrors(ctx context.Context, request ListFileErrorsRequestObject) (ListFileErrorsResponseObject, error)
	// ListHistory История расхода по видам и периодам (O17)
	// (GET /history)
	ListHistory(ctx context.Context, request ListHistoryRequestObject) (ListHistoryResponseObject, error)
	// GetCurrentShares Действующая (последняя) версия долей со строками
	// (GET /shares/current)
	GetCurrentShares(ctx context.Context, request GetCurrentSharesRequestObject) (GetCurrentSharesResponseObject, error)
	// ListShareVersions Версии долей район -> клиника с основанием (O16), новые первыми
	// (GET /shares/versions)
	ListShareVersions(ctx context.Context, request ListShareVersionsRequestObject) (ListShareVersionsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// ListEstimates operation middleware
func (sh *strictHandler) ListEstimates(w http.ResponseWriter, r *http.Request) {
	var request ListEstimatesRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.ListEstimates(ctx, request.(ListEstimatesRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ListEstimates")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(ListEstimatesResponseObject); ok {
		if err := validResponse.VisitListEstimatesResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

